//! Parse only bytes read through an authorized handle, in a separate process.
use crate::{PermissionLevel, Tool, ToolContext, ToolResult};
use async_trait::async_trait;
use base64::{engine::general_purpose::STANDARD, Engine};
use claurst_core::types::{ContentBlock, ImageSource};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{io, process::Stdio, time::Duration};
use tokio::io::{AsyncReadExt, AsyncWriteExt};

#[derive(Deserialize)]
struct Input {
    file_path: String,
    offset: Option<usize>,
    limit: Option<usize>,
}

#[derive(Deserialize)]
struct Part {
    index: usize,
    text: String,
}
#[derive(Deserialize)]
struct ParsedDocument {
    parts: Vec<Part>,
    total: usize,
    error: Option<String>,
    image: Option<RenderedImage>,
}
#[derive(Deserialize)]
struct RenderedImage {
    width: usize,
    height: usize,
    mime_type: String,
    data: String,
}
#[derive(Clone, Copy, PartialEq)]
enum ReadMode {
    Text,
    Recognize,
    Image,
    ValidatePDF,
}
#[derive(Serialize)]
struct Locator {
    unit: &'static str,
    first: usize,
    last: usize,
    total: usize,
    recognition: bool,
    visual: bool,
}
#[derive(Serialize)]
struct Source {
    path: std::path::PathBuf,
    locator: Locator,
}
#[derive(Serialize)]
struct ReadResult {
    source: Source,
    content: String,
    #[serde(skip)]
    image: Option<ContentBlock>,
}

// The parser sees stdin bytes and system frameworks, not user files or network.
const POLICY: &str = r#"
(version 1)
(deny default)
(allow process-exec)
(allow sysctl-read)
(allow file-read* file-map-executable
  (literal "/") (subpath "/System") (subpath "/usr/lib")
  (literal (param "PARSER")) (literal "/dev/null") (literal "/dev/urandom"))
(allow file-read-metadata (literal "/") (path-ancestors (param "PARSER")))
(allow file-write-data (literal "/dev/null"))
"#;

// Vision compiles system models into a disposable cache. Only its compute
// service receives read extensions for that directory; user files and network
// remain inaccessible. Keep ordinary PDF/Word parsing on the smaller policy.
const RECOGNITION_POLICY: &str = r#"
(version 1)
(deny default)
(allow process-exec (literal (param "PARSER")))
(allow sysctl-read)
(allow file-read* file-map-executable
  (literal "/") (subpath "/System") (subpath "/usr/lib")
  (literal (param "PARSER")) (literal "/dev/null") (literal "/dev/urandom"))
(allow file-read-metadata (literal "/") (path-ancestors (param "PARSER")))
(allow file-write-data (literal "/dev/null"))
(allow iokit-open (iokit-user-client-class "IOSurfaceRootUserClient") (iokit-user-client-class "AGXDeviceUserClient"))
(allow file-read-metadata (path-ancestors (param "CACHE")))
(allow system-info (info-type "vfs.disk-space"))
(allow file-read* (subpath "/usr/share/icu"))
(allow file-read-data (literal (param "BUNDLE")))
(allow file-read* file-write* (subpath (param "CACHE")))
(allow file-issue-extension (subpath (param "CACHE")))
(allow iokit-open (iokit-user-client-class "H1xANELoadBalancerDirectPathClient"))
(allow mach-lookup (global-name "com.apple.appleneuralengine"))
"#;

pub async fn read_document(value: Value, ctx: &ToolContext) -> ToolResult {
    document_result(read(value, ctx, ReadMode::Text).await)
}

/// Validate generated bytes through the same bounded, isolated PDF parser.
/// This does not claim that the content or page layout has been reviewed.
pub async fn validate_pdf(path: &std::path::Path, ctx: &ToolContext) -> anyhow::Result<usize> {
    Ok(read(
        json!({"file_path": path, "offset": 1, "limit": 1}),
        ctx,
        ReadMode::ValidatePDF,
    )
    .await?
    .source
    .locator
    .total)
}

pub struct RecognizeText;
#[async_trait]
impl Tool for RecognizeText {
    fn name(&self) -> &str {
        "RecognizeText"
    }
    fn description(&self) -> &str {
        "优先本地识别 PNG/JPEG 图片或扫描 PDF 的中文、英文印刷文字。返回实际页码、像素区域、置信分数与待核对内容；数字必须对照原图，不推测手写、公式、表格结构或缺页。offset 从 1 开始，默认每次 1 页，limit 最多 5 页；图片仅 offset=1。每文件最多 32 MiB，图片最多 2000 万像素，原文件不修改。只将识别文本交给当前模型；不把文字识别当作视觉理解。"
    }
    fn permission_level(&self) -> PermissionLevel {
        PermissionLevel::ReadOnly
    }
    fn self_gates(&self) -> bool {
        true
    }
    fn input_schema(&self) -> Value {
        json!({"type":"object","required":["file_path"],"additionalProperties":false,"properties":{
            "file_path":{"type":"string"}, "offset":{"type":"integer","minimum":1},
            "limit":{"type":"integer","minimum":1,"maximum":5}
        }})
    }
    async fn execute(&self, value: Value, ctx: &ToolContext) -> ToolResult {
        document_result(read(value, ctx, ReadMode::Recognize).await)
    }
}

pub struct ReadImage {
    pub enabled: bool,
}
#[async_trait]
impl Tool for ReadImage {
    fn name(&self) -> &str {
        "ReadImage"
    }
    fn description(&self) -> &str {
        "查看 PNG/JPEG 图片或所选 PDF 页面的实际像素，仅在当前服务已通过图像能力检查时可用。文字提取优先 RecognizeText；需要视觉理解时调用本工具，把选中图片的归一化副本发送给当前模型。返回路径和图像位置，不改原件，不把模型解释当作已核实事实。每次 1 页或 1 张，offset 是 PDF 页码（从 1 开始），limit 只能为 1。输入最多 32 MiB、图片 2000 万像素，输出最长边 1600 像素。"
    }
    fn permission_level(&self) -> PermissionLevel {
        PermissionLevel::ReadOnly
    }
    fn self_gates(&self) -> bool {
        true
    }
    fn input_schema(&self) -> Value {
        json!({"type":"object","required":["file_path"],"additionalProperties":false,"properties":{
            "file_path":{"type":"string"}, "offset":{"type":"integer","minimum":1},
            "limit":{"type":"integer","enum":[1]}
        }})
    }
    async fn execute(&self, value: Value, ctx: &ToolContext) -> ToolResult {
        if !self.enabled {
            return ToolResult::error("当前模型的图像输入未验证，未读取或发送图片。请在模型设置中选择支持图像的非 Claude 服务并检查连接；印刷文字可先使用 RecognizeText 本地识别。");
        }
        document_result(read(value, ctx, ReadMode::Image).await)
    }
}

fn document_result(result: anyhow::Result<ReadResult>) -> ToolResult {
    match result {
        Ok(result) => match serde_json::to_string(&result) {
            Ok(content) => {
                ToolResult::success(content).with_images(result.image.into_iter().collect())
            }
            Err(error) => ToolResult::error(format!("文档来源无法编码：{error}")),
        },
        Err(error) => ToolResult::error(format!("未完成文档读取：{error}")),
    }
}

async fn read(value: Value, ctx: &ToolContext, mode: ReadMode) -> anyhow::Result<ReadResult> {
    let recognition = mode == ReadMode::Recognize;
    let visual = mode == ReadMode::Image;
    let input: Input = serde_json::from_value(value)?;
    let first = input.offset.unwrap_or(1);
    let limit = input
        .limit
        .unwrap_or(if mode == ReadMode::Text { 10 } else { 1 });
    let maximum = match mode {
        ReadMode::Text => 20,
        ReadMode::Recognize => 5,
        ReadMode::Image | ReadMode::ValidatePDF => 1,
    };
    anyhow::ensure!(
        first > 0 && (1..=maximum).contains(&limit),
        "offset 从 1 开始；文字读取 limit 最多 20 页/段，扫描识别最多 5 页，视觉读取每次 1 页/张"
    );
    let path = ctx.resolve_path(&input.file_path);
    let grant = ctx.check_permission_for_path(
        "Read",
        &format!("读取文档 {}", path.display()),
        path.clone(),
        true,
    )?;
    let file = crate::open_regular_file(&path)?;
    let path = ctx
        .confirm_opened_path("Read", "读取文档", &path, &file, grant, true)
        .map_err(anyhow::Error::msg)?;
    let mut bytes = Vec::new();
    tokio::fs::File::from_std(file)
        .take(32 * 1024 * 1024 + 1)
        .read_to_end(&mut bytes)
        .await?;
    anyhow::ensure!(bytes.len() <= 32 * 1024 * 1024, "文档超过 32 MiB，未解析");
    let is_word = path
        .extension()
        .is_some_and(|ext| ext.eq_ignore_ascii_case("docx"));
    let extension = path
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if recognition {
        anyhow::ensure!(
            matches!(extension.as_str(), "pdf" | "png" | "jpg" | "jpeg"),
            "本地文字识别仅支持 PNG、JPEG 或未加密 PDF，请提供清晰原件"
        );
    }
    if visual {
        anyhow::ensure!(
            matches!(extension.as_str(), "pdf" | "png" | "jpg" | "jpeg"),
            "视觉读取仅支持 PNG/JPEG 或未加密 PDF，请提供清晰原件"
        );
    }
    let image = (recognition || visual) && extension != "pdf";
    if is_word {
        anyhow::ensure!(
            !bytes.starts_with(&[0xd0, 0xcf, 0x11, 0xe0]),
            "加密或旧式 Word 容器暂不支持，请另存为未加密 .docx；未读取内容"
        );
        let mut archive = zip::ZipArchive::new(io::Cursor::new(bytes))
            .map_err(|error| anyhow::anyhow!("DOCX 损坏或格式无效：{error}"))?;
        anyhow::ensure!(archive.len() <= 4096, "DOCX 内部项目过多，未解析");
        let entry = archive.by_name("word/document.xml").map_err(|error| {
            anyhow::anyhow!("无法读取 DOCX 正文（可能损坏、加密或不是受支持的 Word 文件）：{error}")
        })?;
        anyhow::ensure!(!entry.encrypted(), "加密 DOCX 暂不支持；未读取内容");
        anyhow::ensure!(
            entry.size() <= 16 * 1024 * 1024,
            "DOCX 正文展开超过 16 MiB，未解析"
        );
        let mut xml = Vec::new();
        std::io::Read::read_to_end(
            &mut std::io::Read::take(entry, 16 * 1024 * 1024 + 1),
            &mut xml,
        )?;
        anyhow::ensure!(
            xml.len() <= 16 * 1024 * 1024,
            "DOCX 正文展开超过 16 MiB，未解析"
        );
        bytes = xml;
    }
    anyhow::ensure!(!ctx.cancel_token.is_cancelled(), "读取已停止");
    let executable = std::env::current_exe()?;
    let parser = executable
        .parent()
        .ok_or_else(|| io::Error::other("无法定位内置文档解析器"))?
        .join("claurst-document-parser");
    anyhow::ensure!(parser.is_file(), "内置文档解析器缺失，请重新安装或构建应用");
    // macOS may launch the bundle through /tmp while sandbox paths use
    // /private/tmp. Match the actual file before creating literal rules.
    let parser = parser.canonicalize()?;
    let cache = if recognition {
        let directory = tempfile::Builder::new().prefix("claurst-ocr-").tempdir()?;
        std::fs::create_dir_all(directory.path().join("Library/Caches"))?;
        Some(directory)
    } else {
        None
    };
    let mut command = tokio::process::Command::new(claurst_core::sandbox::SEATBELT_EXECUTABLE);
    command
        .args([
            "-p",
            if recognition {
                RECOGNITION_POLICY
            } else {
                POLICY
            },
        ])
        .arg(format!("-DPARSER={}", parser.display()))
        .env_clear();
    if let Some(cache) = &cache {
        let path = cache.path().canonicalize()?;
        command
            .arg(format!("-DCACHE={}", path.display()))
            .arg(format!(
                "-DBUNDLE={}",
                parser
                    .parent()
                    .ok_or_else(|| io::Error::other("无法定位解析器目录"))?
                    .display()
            ))
            // CoreFoundation's cache lookup must not fall back to the user's
            // Library. If a future OS ignores this override, Seatbelt denies it.
            .env("CFFIXED_USER_HOME", &path)
            .env("TMPDIR", &path);
    }
    let mut child = command
        .arg("--")
        .arg(parser)
        .args([
            if visual && image {
                "view-image"
            } else if visual {
                "view-pdf"
            } else if image {
                "ocr-image"
            } else if recognition {
                "ocr-pdf"
            } else if mode == ReadMode::ValidatePDF {
                "validate-pdf"
            } else if is_word {
                "docx"
            } else {
                "pdf"
            },
            &first.to_string(),
            &limit.to_string(),
        ])
        .current_dir("/")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .kill_on_drop(true)
        .spawn()?;
    let mut input_pipe = child
        .stdin
        .take()
        .ok_or_else(|| io::Error::other("无法发送文档内容"))?;
    let output_pipe = child
        .stdout
        .take()
        .ok_or_else(|| io::Error::other("无法读取解析结果"))?;
    let mut output = Vec::new();
    let output_limit = if visual { 6 * 1024 * 1024 } else { 1024 * 1024 };
    let operation = async {
        let writer = async move {
            input_pipe.write_all(&bytes).await?;
            input_pipe.shutdown().await?;
            drop(input_pipe);
            Ok::<(), io::Error>(())
        };
        let reader = async {
            output_pipe
                .take(output_limit + 1)
                .read_to_end(&mut output)
                .await
        };
        let (_, _, status) = tokio::try_join!(writer, reader, child.wait())?;
        anyhow::ensure!(status.success(), "本地解析器异常结束，未取得可引用内容");
        anyhow::ensure!(output.len() as u64 <= output_limit, "解析结果过大，未接收");
        Ok::<(), anyhow::Error>(())
    };
    let outcome = tokio::select! {
        biased;
        _ = ctx.cancel_token.cancelled() => Err(anyhow::anyhow!("文档读取已停止")),
        result = tokio::time::timeout(Duration::from_secs(if recognition { 90 } else { 20 }), operation) =>
            result.unwrap_or_else(|_| Err(anyhow::anyhow!("本地解析或识别超时，未取得可引用内容；请缩小页数或图片后重试"))),
    };
    if let Err(error) = outcome {
        // Reap the parser before its private cache is removed on cancellation.
        let _ = child.kill().await;
        return Err(error);
    }
    let parsed: ParsedDocument = serde_json::from_slice(&output)?;
    if let Some(error) = parsed.error {
        anyhow::bail!(error);
    }
    anyhow::ensure!(!parsed.parts.is_empty(), "没有可引用的文档内容");
    let image_block = if visual {
        let rendered = parsed
            .image
            .ok_or_else(|| anyhow::anyhow!("解析器未返回可查看的图像"))?;
        anyhow::ensure!(
            parsed.parts.len() == 1
                && (200..=1600).contains(&rendered.width)
                && (200..=1600).contains(&rendered.height),
            "解析器返回了无效的图像范围"
        );
        let decoded = STANDARD.decode(&rendered.data)?;
        anyhow::ensure!(
            decoded.len() <= 4 * 1024 * 1024
                && ((rendered.mime_type == "image/png"
                    && decoded.starts_with(b"\x89PNG\r\n\x1a\n"))
                    || (rendered.mime_type == "image/jpeg" && decoded.starts_with(&[0xff, 0xd8]))),
            "解析器返回了无效的图像编码"
        );
        Some(ContentBlock::Image {
            source: ImageSource {
                source_type: "base64".into(),
                media_type: Some(rendered.mime_type),
                data: Some(rendered.data),
                url: None,
            },
        })
    } else {
        None
    };
    let unit = if image {
        "张"
    } else if is_word {
        "段"
    } else {
        "页"
    };
    let mut content = String::new();
    let mut last = first;
    for part in parsed.parts {
        anyhow::ensure!(
            part.index >= first && part.index - first < limit && part.index <= parsed.total,
            "解析器返回了无效页码"
        );
        content.push_str(&format!("第 {} {unit}\n{}\n\n", part.index, part.text));
        last = part.index;
    }
    if last < parsed.total {
        content.push_str(&format!(
            "[共 {} {unit}；继续读取请使用 offset={}]",
            parsed.total,
            last + 1
        ));
    }
    Ok(ReadResult {
        source: Source {
            path,
            locator: Locator {
                unit: if image {
                    "image"
                } else if is_word {
                    "paragraph"
                } else {
                    "page"
                },
                first,
                last,
                total: parsed.total,
                recognition,
                visual,
            },
        },
        content,
        image: image_block,
    })
}
